"""Generate the customer preparation flow and public broker resource directory."""
from html import escape
import json

def build_extra_pages(out, head, header, footer, props, wa, absolute_assets):
    def page(path,title,description,content):
        target=out/path.strip('/');target.mkdir(exist_ok=True)
        html='<!doctype html><html lang="pt-BR">'+head(title,description,path,'tools')+'<script src="/site-tools.js" defer></script><body><a class="skip" href="#inicio">Pular para o conteúdo</a>'+header+content+footer+'</body></html>'
        (target/'index.html').write_text(absolute_assets(html))
    options=''.join(f'<option value="{p["id"]}">{p["name"]}</option>' for p in props)
    def select(name,label,values,help=''):
        return f'<label class="form-field" for="{name}"><span>{label}</span><select id="{name}" name="{name}">'+''.join(f'<option value="{escape(v,quote=True)}">{escape(v)}</option>' for v in values)+f'</select>{"<small>"+help+"</small>" if help else ""}</label>'
    region=select('regiao','Região de interesse',['Quero explorar as opções','Zona Sul','Zona Leste','Zona Oeste','Zona Norte','Jundiaí'])
    beds=select('dormitorios','Dormitórios',['Quero ver as possibilidades','1 dormitório','2 dormitórios','3 dormitórios'])
    purpose=select('objetivo','O que você tem em mente?',['Moradia','Investimento','Ainda estou decidindo'])
    time=select('momento','Quando pretende comprar?',['Estou pesquisando','Nos próximos 3 meses','Entre 3 e 6 meses','Depois de 6 meses'])
    income=select('renda','Renda familiar mensal · opcional',['Prefiro conversar no atendimento','Até R$ 3 mil','De R$ 3 mil a R$ 5 mil','De R$ 5 mil a R$ 8 mil','De R$ 8 mil a R$ 12 mil','Acima de R$ 12 mil'],'Somente uma referência para a conversa. Não é análise de crédito.')
    entry=select('entrada','Valor planejado para entrada · opcional',['Ainda estou planejando','Até R$ 20 mil','De R$ 20 mil a R$ 50 mil','De R$ 50 mil a R$ 100 mil','Acima de R$ 100 mil','Prefiro conversar no atendimento'])
    finance=select('pagamento','Como imagina pagar?',['Quero entender as opções','Pretendo financiar','Quero avaliar compra à vista'])
    content=f'''<main id="inicio" class="wrap tools-page"><nav class="breadcrumbs" aria-label="Caminho de navegação"><a href="/">Início</a><span>/</span><span aria-current="page">Prepare seu atendimento</span></nav><div class="planning-layout"><div class="planning-intro"><p class="eyebrow"><span></span> SUA BUSCA, COM MAIS CLAREZA</p><h1>Uma boa conversa<br>começa com você.</h1><p>Conte o que procura e em que momento está. A Ferrari recebe um resumo das suas escolhas para ajudar no próximo passo.</p><ol class="planning-benefits"><li><strong>Seu objetivo</strong>Moradia ou investimento. A escolha começa pelo seu plano.</li><li><strong>Seu momento</strong>Pesquisando ou pronto para avançar, você é bem-vindo.</li><li><strong>Uma conversa direta</strong>Revise o resumo e envie pelo seu WhatsApp.</li></ol><a class="text-link" href="{wa('Olá! Prefiro conversar diretamente sobre meu próximo imóvel.')}" target="_blank" rel="noopener noreferrer">Prefiro falar direto com a Ferrari <i data-icon="arrow-up-right"></i></a></div><div class="planning-card"><noscript><p>Para montar seu resumo, habilite o JavaScript ou use o atendimento direto ao lado.</p><style>#planning-form{{display:none}}</style></noscript><form id="planning-form" autocomplete="off"><div class="form-progress" aria-label="Etapas do atendimento"><span data-step-indicator="0" aria-current="step">1. Preferências</span><span data-step-indicator="1">2. Seu momento</span><span data-step-indicator="2">3. Resumo</span></div><fieldset data-form-step="0"><legend>O que faz sentido para você?</legend><label class="form-field" for="empreendimento"><span>Já tem um empreendimento em mente?</span><select id="empreendimento" name="empreendimento"><option value="">Quero ajuda para escolher</option>{options}</select></label><div class="form-grid">{region}{beds}</div>{purpose}<p class="form-note">Você pode explorar possibilidades sem informar nome, telefone ou documentos.</p><button type="button" class="btn btn-red" data-form-next>Continuar <i data-icon="arrow-right"></i></button></fieldset><fieldset data-form-step="1" hidden><legend>Vamos entender seu momento.</legend>{time}{finance}<details class="optional-finance"><summary>Quero adiantar meu planejamento financeiro <span>Opcional</span></summary><p>Se preferir, deixe para conversar com a equipe.</p>{income}{entry}</details><p class="form-note">Este roteiro não calcula parcelas, subsídios ou aprovação de financiamento.</p><div class="form-actions"><button type="button" class="text-btn" data-form-back>Voltar</button><button type="button" class="btn btn-red" data-form-next>Revisar resumo <i data-icon="arrow-right"></i></button></div></fieldset><fieldset data-form-step="2" hidden><legend>Seu próximo passo, com contexto.</legend><p>Confira a mensagem. Você pode voltar e ajustar suas escolhas antes de abrir o WhatsApp.</p><pre id="planning-summary" class="planning-summary" aria-live="polite"></pre><p class="form-note">Ao abrir o WhatsApp, você escolhe se deseja enviar a mensagem à Ferrari. Suas respostas não ficam salvas neste site. <a href="/privacidade/">Entenda a privacidade.</a></p><div class="form-actions"><button type="button" class="text-btn" data-form-back>Ajustar escolhas</button><a id="planning-send" class="btn btn-red" href="{wa('Olá! Quero conversar sobre meu próximo imóvel.')}" target="_blank" rel="noopener noreferrer"><i data-icon="whatsapp"></i> Abrir no WhatsApp</a></div></fieldset></form></div></div></main>'''
    page('/atendimento/','Prepare seu atendimento | Ferrari Imóveis','Conte suas preferências e seu momento de compra. Revise um resumo e converse com a Ferrari pelo WhatsApp, com informações para orientar seu próximo passo.',content)
    cards=[]
    for p in props:
        links=p['links'];book=f'<a href="{links["book"]}" target="_blank" rel="noopener noreferrer"><i data-icon="file"></i>Book do empreendimento</a>' if links.get('book') else f'<a href="{wa("Olá! Gostaria de receber o book do "+p["name"]+".")}" target="_blank" rel="noopener noreferrer"><i data-icon="file"></i>Solicitar book</a>'
        table=f'<a href="{links["tabela"]}" target="_blank" rel="noopener noreferrer"><i data-icon="file"></i>Tabela de referência · {p["tableReference"]}</a>' if links.get('tabela') and p.get('tableReference') else ''
        tour=f'<a href="{links["tour"]}" target="_blank" rel="noopener noreferrer"><i data-icon="play"></i>Tour virtual</a>' if links.get('tour') else ''
        cards.append(f'''<article class="material-card" data-material-name="{escape(p['name']+' '+p['neighborhood']+' '+p['regionLabel'],quote=True)}" data-material-region="{p['region']}"><img src="/{p['image']}" alt="{p['name']}, perspectiva ilustrativa" width="700" height="440" loading="lazy" decoding="async"><div><p class="eyebrow">{p['regionLabel']} · {p['neighborhood']}</p><h2>{p['name']}</h2><p>{' e '.join(map(str,p['beds']))} dormitórios · {p['area']} m²</p><div class="resource-links"><a href="/imoveis/{p['id']}/"><i data-icon="home"></i>Ficha e imagens</a>{book}{tour}{table}<a href="{wa('Olá! Preciso da tabela atualizada e das condições do '+p['name']+'.')}" target="_blank" rel="noopener noreferrer"><i data-icon="whatsapp"></i>Solicitar tabela atualizada</a></div><button class="text-link" data-copy-property="{p['id']}" data-title="{p['name']}">Copiar link para o cliente <i data-icon="share"></i></button></div></article>''')
    content='''<main id="inicio" class="wrap tools-page"><nav class="breadcrumbs" aria-label="Caminho de navegação"><a href="/">Início</a><span>/</span><span aria-current="page">Materiais para corretores</span></nav><div class="section-top materials-heading"><div><p class="eyebrow"><span></span> EQUIPE FERRARI</p><h1>Informação à mão.<br>Mais tempo para atender.</h1></div><p class="section-description">Encontre apresentações, tours e páginas para compartilhar. Consulte a equipe para receber a tabela comercial vigente.</p></div><div class="materials-toolbar"><label class="catalog-search"><i data-icon="search"></i><input type="search" id="material-search" aria-label="Buscar materiais por empreendimento ou bairro" placeholder="Empreendimento ou bairro" maxlength="120"></label><label class="form-field"><span>Região</span><select id="material-region"><option value="all">Todas as regiões</option><option value="sul">Zona Sul</option><option value="leste">Zona Leste</option><option value="oeste">Zona Oeste</option><option value="norte">Zona Norte</option><option value="jundiai">Jundiaí</option></select></label></div><p id="material-count" role="status" aria-live="polite">14 empreendimentos</p><div class="materials-grid">'''+''.join(cards)+'''</div><p id="material-empty" class="empty-state" hidden>Nenhum material com essa busca. Experimente outro bairro ou região.</p><div class="materials-note"><i data-icon="file"></i><p><strong>Condições comerciais mudam.</strong> As tabelas e promoções devem ser confirmadas com a equipe antes de apresentar uma proposta. Os books e tours abrem em serviços externos.</p></div><div id="toast" class="toast" role="status" aria-live="polite"></div></main>'''
    page('/materiais/','Materiais para corretores | Equipe Ferrari','Central de materiais da Equipe Ferrari: apresentações, tours, fichas dos empreendimentos e links para compartilhar com clientes em São Paulo e Jundiaí.',content)
